package com.concertstage.stage;
import com.concertstage.block.*;import com.concertstage.item.AngleToolItem;import java.util.*;import net.minecraft.core.*;import net.minecraft.world.*;import net.minecraft.world.item.context.*;import net.minecraft.world.level.Level;
/** Precise mounts only; the existing grid and motor placement remains the fallback. */
public final class StageRigging{
 private StageRigging(){}private static double distance(double[] a,double[] b){double d=0;for(int i=0;i<3;i++)d+=(a[i]-b[i])*(a[i]-b[i]);return d;}
 private static boolean compatible(StageSpec.Port a,double[] ac,double aa,StageSpec.Port b,double[] bc,double ba){double[] an=StagePose.rotate(a.normal[0],a.normal[1],a.normal[2],aa),bn=StagePose.rotate(b.normal[0],b.normal[1],b.normal[2],ba);if(an[0]*bn[0]+an[1]*bn[1]+an[2]*bn[2]>-.999||a.points.length!=b.points.length)return false;for(double[] p:a.points){double[] w=StagePose.point(p,ac[0],ac[1],ac[2],aa);boolean found=false;for(double[] q:b.points)if(distance(w,StagePose.point(q,bc[0],bc[1],bc[2],ba))<.000004){found=true;break;}if(!found)return false;}return true;}
 public static boolean connected(StageModules.Piece a,StageModules.Piece b){if(a.spec().ports==null||b.spec().ports==null)return false;double[] ac={a.x(),a.y(),a.z()},bc={b.x(),b.y(),b.z()};for(var p:a.spec().ports)for(var q:b.spec().ports)if(compatible(p,ac,a.entry().degrees(),q,bc,b.entry().degrees()))return true;return false;}
 public static InteractionResult truss(BlockPlaceContext ctx,MultiPartBlock block){Level l=ctx.getLevel();BlockPos clicked=ctx.replacingClickedOnBlock()?ctx.getClickedPos():ctx.getClickedPos().relative(ctx.getClickedFace().getOpposite());String key=net.minecraft.core.registries.BuiltInRegistries.BLOCK.getKey(block).getPath();StageSpec model=StageSpec.find(key);if(model==null||!model.kind.equals("truss"))return InteractionResult.PASS;StageModules.Piece parent=StageModules.nearest(l,clicked,ctx.getClickLocation(),"truss");double x,y,z,angle;String support;
 if(parent!=null){StageSpec.Port chosen=null;double best=1e30;double[] po={parent.x(),parent.y(),parent.z()},hit={ctx.getClickLocation().x,ctx.getClickLocation().y,ctx.getClickLocation().z};for(var p:parent.spec().ports){double[] n=StagePose.rotate(p.normal[0],p.normal[1],p.normal[2],parent.entry().degrees());if(n[0]*ctx.getClickedFace().getStepX()+n[1]*ctx.getClickedFace().getStepY()+n[2]*ctx.getClickedFace().getStepZ()<.99)continue;double d=distance(hit,StagePose.point(p.center,po[0],po[1],po[2],parent.entry().degrees()));if(d<best){best=d;chosen=p;}}if(chosen==null||best>1.2)return StageModules.fail(ctx,"rig_click_connector");double[] end=StagePose.point(chosen.center,po[0],po[1],po[2],parent.entry().degrees()),result=null;double yaw=0,desired=StageSpec.turns(block.placementFacing(ctx))*90.+AngleToolItem.bendOf(ctx.getPlayer());List<Integer> order=new ArrayList<>(List.of(0,1,2,3));order.sort(Comparator.comparingDouble(q->Math.abs(Math.IEEEremainder(parent.entry().degrees()+q*90.-desired,360))));for(int q:order){if(result!=null)break;double a=parent.entry().degrees()+q*90.;for(var p:model.ports){double[] v=StagePose.rotate(p.center[0],p.center[1],p.center[2],a),o={end[0]-v[0],end[1]-v[1],end[2]-v[2]};if(compatible(chosen,po,parent.entry().degrees(),p,o,a)){result=o;yaw=a;break;}}}if(result==null)return StageModules.fail(ctx,"rig_incompatible");x=result[0];y=result[1];z=result[2];angle=yaw;support="piece:"+parent.entry().token();}
 else{var s=StageSurfaces.at(l,clicked);if(s==null)return InteractionResult.PASS;if(ctx.getClickedFace()!=Direction.UP||Math.abs(ctx.getClickLocation().y-s.y())>.15)return StageModules.fail(ctx,"rig_click_deck_top");angle=StageSpec.turns(block.placementFacing(ctx))*90.+AngleToolItem.bendOf(ctx.getPlayer());double rel=angle-s.turn()*90.;double[] center=StagePose.rotate(.5,0,.5,rel),b=StagePose.box(model.raw_bounds,-center[0],0,-center[2],rel),h=s.local(ctx.getClickLocation());double lx=-b[0],hx=s.width()-b[3],lz=-b[2],hz=s.depth()-b[5],px=Math.rint(h[0]*16)/16.,pz=Math.rint(h[2]*16)/16.;double[] pivot=s.point(px,pz),v=StagePose.rotate(.5,0,.5,angle);x=pivot[0]-v[0];y=s.y()-model.raw_bounds[1];z=pivot[2]-v[2];support="ground";if(!StageSurfaces.supported(l,model,x,y,z,angle)){if(lx>hx+.001||lz>hz+.001)return StageModules.fail(ctx,"rig_no_support");pivot=s.point(Math.max(lx,Math.min(hx,px)),Math.max(lz,Math.min(hz,pz)));x=pivot[0]-v[0];z=pivot[2]-v[2];if(!StageSurfaces.supported(l,model,x,y,z,angle))return StageModules.fail(ctx,"rig_no_support");}}
 if(!StageModules.place(ctx,model,x,y,z,angle,key+"=1",support,null,Map.of()))return StageModules.fail(ctx,"space_blocked");if(!l.isClientSide&&(ctx.getPlayer()==null||!ctx.getPlayer().getAbilities().instabuild))ctx.getItemInHand().shrink(1);return InteractionResult.sidedSuccess(l.isClientSide);}
 public record TowerPlan(BlockPlaceContext context,StageSpec adapter,double x,double y,double z,BlockPos root){}
 public static TowerPlan towerPlan(BlockPlaceContext ctx,MotorTowerBlock tower){if(tower.isHoist())return null;Level l=ctx.getLevel();BlockPos clicked=ctx.replacingClickedOnBlock()?ctx.getClickedPos():ctx.getClickedPos().relative(ctx.getClickedFace().getOpposite());var s=StageSurfaces.at(l,clicked);if(s==null)return null;double yaw=Math.toRadians(AngleToolItem.bendOf(ctx.getPlayer()));if(1.21875*(Math.abs(Math.cos(yaw))+Math.abs(Math.sin(yaw)))>1.5+.001||ctx.getClickedFace()!=Direction.UP||Math.abs(ctx.getClickLocation().y-s.y())>.15)return new TowerPlan(null,null,0,0,0,null);int y=(int)Math.ceil(s.y()-1e-6);List<BlockPos> candidates=new ArrayList<>();candidates.add(BlockPos.containing(ctx.getClickLocation().x,y,ctx.getClickLocation().z));double lo=1.5,hx=Math.floor(s.width()-1.5)+.5,hz=Math.floor(s.depth()-1.5)+.5;if(hx>=lo&&hz>=lo){double[] hit=s.local(ctx.getClickLocation()),p=s.point(Math.max(lo,Math.min(hx,Math.floor(hit[0])+.5)),Math.max(lo,Math.min(hz,Math.floor(hit[2])+.5)));candidates.add(BlockPos.containing(p[0],y,p[2]));}for(BlockPos root:candidates){double delta=root.getY()-s.y();StageSpec adapter=null;if(delta>.001){adapter=StageSpec.find(String.format(Locale.ROOT,"tower_stage_adapter_%03d",(int)Math.round(delta*1000)));if(adapter==null)continue;}StageSpec feet=adapter==null?StageSpec.get("tower_stage_adapter_100"):adapter;double x=root.getX()-1.,z=root.getZ()-1.;if(!StageSurfaces.supported(l,feet,x,s.y(),z,0))continue;BlockPlaceContext relocated=new BlockPlaceContext(ctx){public BlockPos getClickedPos(){return root;}public boolean replacingClickedOnBlock(){return true;}};if(tower.getStateForPlacement(relocated)!=null)return new TowerPlan(relocated,adapter,x,s.y(),z,root);}return new TowerPlan(null,null,0,0,0,null);}
 public static boolean placeAdapter(BlockPlaceContext ctx,TowerPlan p){return p.adapter==null||StageModules.place(ctx,p.adapter,p.x,p.y,p.z,0,"","tower@"+p.root.getX()+","+p.root.getY()+","+p.root.getZ(),null,Map.of());}
 public static void discardAdapter(Level l,TowerPlan p){if(p.adapter==null)return;for(int x=0;x<3;x++)for(int z=0;z<3;z++){BlockPos at=BlockPos.containing(p.x+x,p.y,p.z+z);for(var e:StageModules.entries(l,at))if(e.key().equals(p.adapter.id)){StageModules.remove(l,new StageModules.Piece(at,e),null,false);return;}}}
}
